const { watch } = require('chokidar');

const content = fs.mkdtempSync(path.join(os.tmpdir(), 'c-'));
const tpl = fs.mkdtempSync(path.join(os.tmpdir(), 't-'));
fs.writeFileSync(path.join(content, 'hello.md'), '# one\n');

const w = watch([content, tpl], { ignoreInitial: true });
w.on('all', (event, p) => console.log('EVENT', event, p));
w.on('error', (e) => console.log('ERROR', e));

setTimeout(() => {
  console.log('writing...');
  fs.writeFileSync(path.join(content, 'hello.md'), '# two\n');
}, 500);

setTimeout(async () => { await w.close(); process.exit(0); }, 2500);
