export PATH="$HOME/.nvm/versions/node/v22.23.2/bin:$PATH"; cat > dbg5.js <<'EOF'
const fs = require('fs');
const os = require('os');
const path = require('path');
const net = require('net');
const { DevServer } = require('./dist/server.js');
function tmpDir(p){return fs.mkdtempSync(path.join(os.tmpdir(),p));}
function getFreePort(){return new Promise((res,rej)=>{const s=net.createServer();s.once('error',rej);s.listen(0,'127.0.0.1',()=>{const a=s.address();const p=typeof a==='object'&&a?a.port:0;s.close(()=>res(p));});});}
(async()=>{
  const content=tmpDir('dbg-content-'); const out=tmpDir('dbg-out-'); const tpl=tmpDir('dbg-tpl-');
  fs.mkdirSync(path.join(tpl,'layouts'),{recursive:true});
  fs.writeFileSync(path.join(tpl,'layouts','default.hbs'),'<html><body>{{{body}}}</body></html>');
  fs.writeFileSync(path.join(tpl,'page.hbs'),'<main>{{{html}}}</main>');
  fs.writeFileSync(path.join(tpl,'index.hbs'),'<main>{{#each pages}}<a href="{{slug}}.html">{{title}}</a>{{/each}}</main>');
  fs.writeFileSync(path.join(content,'hello.md'),'---\ntitle: Hello\n---\n# Version One\n');
  const port=await getFreePort();
  const server=new DevServer({contentDir:content,outputDir:out,templatesDir:tpl,port,host:'127.0.0.1',debounceMs:50});
  await server.start();
  server.watcher.on('all',(e,p)=>console.log('DEV EVENT',e,p));
  server.watcher.on('error',(e)=>console.log('DEV ERR',e));
  fs.writeFileSync(path.join(content,'hello.md'),'---\ntitle: Hello\n---\n# Version Two\n');
  await new Promise(r=>setTimeout(r,1500));
  console.log('V2?', fs.readFileSync(path.join(out,'hello.html'),'utf-8').includes('Version Two'));
  await server.stop(); process.exit(0);
})().catch(e=>{console.error('ERR',e);process.exit(1);});
EOF
